<?php foreach($report['items'] as $item): ?><tr><td><?php if(!$item['trashed_at']): ?><a class="table-title" href="<?=e(route_url($item['published_revision_id']?'article':'edit',['id'=>$item['id']]))?>"><?=e($item['title'])?></a><?php else: ?><strong><?=e($item['title'])?></strong><?php endif; ?><small><?=e($item['category_name'] ?? 'No category')?></small></td><td><span class="badge <?=$item['published_revision_id']?'published':''?>"><?=$item['trashed_at'] ? 'Trash' : ($item['published_revision_id'] ? 'Published' : 'Draft')?></span></td><td class="usage-number"><?=number_format($item['views'])?></td><?php if($period!=='all'): ?><td class="usage-number"><?=number_format($item['lifetime_views'])?></td><?php endif; ?></tr><?php endforeach; ?>
<?php if(!$report['items']): ?><tr><td colspan="<?=$period==='all'?3:4?>" class="table-empty"><?=$search!==''?'No articles match your search.':'No articles yet. Counts will appear as readers use the knowledge base.'?></td></tr><?php endif; ?>
</tbody></table></div>
<?php if($report['pages']>1): ?><nav class="pagination" aria-label="Usage article pages"><?php if($report['page']>1): ?><a class="button secondary" href="<?=e(route_url('usage',['period'=>$period,'search'=>$search,'page'=>$report['page']-1]))?>">← Previous</a><?php endif; ?><span>Page <?=$report['page']?> of <?=$report['pages']?></span><?php if($report['page']<$report['pages']): ?><a class="button secondary" href="<?=e(route_url('usage',['period'=>$period,'search'=>$search,'page'=>$report['page']+1]))?>">Next →</a><?php endif; ?></nav><?php endif; ?>
